<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileGivenNameAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileGivenNameAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileGivenNameAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getGivenName returns null on a freshly created holder.
     */
    public function testGivenNameNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileGivenNameAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isGivenNameAssigned());
        $this->assertNull($holder->getGivenName());
    }
}
class ImplWithUserProfileGivenNameAttributeHolderUnitTest
{
    use UserProfileGivenNameAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedGivenNameRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultGivenName();
    }
}
